export interface NotesSection { title: string; items: string[] }

/** Parses the markdown generated by scripts/release.ts (`### Title` + `- item` lines) into sections. */
export function parseReleaseNotes(body: string | null | undefined): NotesSection[] {
  const sections: NotesSection[] = []
  let current: NotesSection | null = null
  for (const raw of (body ?? '').split(/\r?\n/)) {
    const line = raw.trim()
    if (!line) continue
    const heading = line.match(/^#{1,6}\s+(.+)$/)
    if (heading) { current = { title: heading[1], items: [] }; sections.push(current); continue }
    const text = line.replace(/^[-*]\s+/, '')
    if (!current) { current = { title: '', items: [] }; sections.push(current) }
    current.items.push(text)
  }
  return sections.filter(section => section.items.length)
}
